INSERT INTO v2_gorevler (bolum_id, gorev_adi, sira_no, puan, gorev_tipi, yayinda, icerik_json) SELECT 18, 'Elma Toplayıcı', 8, 25, 'standart', 1, '{"hikaye_metni":{"time":1794225273692,"blocks":[{"type":"paragraph","data":{"text":"Kirpi-kedi Toplar fareyi takip ederek elma topluyor. 🍏"}},{"type":"header","data":{"text":"🎯 Görevin","level":3}},{"type":"paragraph","data":{"text":"<b>Toplar</b>: <b>skor</b>u <b>0</b> yap; <b>sürekli</b>: fare okuna dön, <b>4 adım</b> git; <b>eğer Elma''ya değiyorsa</b>: <b>skor</b>u <b>1</b> değiştir, <b>«yeni elma»</b> yayınla, <b>0.2 saniye</b> bekle. <b>Elma</b>: <b>«yeni elma»</b> mesajını alınca <b>rastgele konuma</b> git."}},{"type":"header","data":{"text":"🧰 Kullanacağın Bloklar","level":3}},{"type":"paragraph","data":{"text":"<span style=\\"display:inline-block;background:#FFBF00;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\">🏳️ Yeşil Bayrak Tıklandığında</span> <span style=\\"display:inline-block;background:#FF8C1A;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\"><b>skor</b> değerini <b>0</b> yap</span> <span style=\\"display:inline-block;background:#FFAB19;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\">sürekli tekrarla</span> <span style=\\"display:inline-block;background:#4C97FF;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\"><b>fare oku</b>''na doğru dön</span> <span style=\\"display:inline-block;background:#4C97FF;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\"><b>4</b> adım git</span> <span style=\\"display:inline-block;background:#FFAB19;color:#fff;border-radius:12px;padding:2px 10px;font-weight:700;font-size:13.5px;box-shadow:0 2px 0 rgba(0,0,0,.18)\\">eğer (<b>Elma</b>''a de